#!/usr/bin/env bash
# SPDX-FileCopyrightText: (C) 2026 Intel Corporation
# SPDX-License-Identifier: Apache-2.0
#
# Generate config/config.yaml from config/base.yaml and the vap-config.yaml
# fragments of the selected VMS (vms_shim/<vms>/) and analytics apps
# (analytics_app_shim/<app>/). ${VAR} placeholders are kept as-is and resolved
# from .env by the backend at startup, so the generated file holds no secrets.

set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
FRAGMENT="vap-config.yaml"
BASE="$ROOT/config/base.yaml"
MARKER="# GENERATED by setup.sh"
VMS_DIR="vms_shim"
APP_DIR="analytics_app_shim"

usage() {
    cat <<EOF
Usage: $(basename "$0") --vms <list> --apps <list> [--output <file>] [--force]
       $(basename "$0") --list

Generate config/config.yaml for the selected VMS and analytics apps.
Run it again, then restart the backend, whenever the selection changes.

Options:
  --vms <list>     Comma-separated VMS to connect, for example: nx,milestone
  --apps <list>    Comma-separated analytics apps to enable, for example: ld,lvc
  --output <file>  Output file (default: config/config.yaml)
  --force          Replace an output file that was not generated by this script;
                   the previous file is kept as <file>.bak
  --list           List the available VMS and apps
  -h, --help       Show this help

Aliases: nx = nxwitness, ld = object_detection.
EOF
}

die() {
    echo "error: $*" >&2
    exit 1
}

warn() {
    echo "warning: $*" >&2
}

# Shims under directory $1 that provide a config fragment.
available() {
    local dir
    for dir in "$ROOT/$1"/*/; do
        if [[ -f "$dir$FRAGMENT" ]]; then
            basename "$dir"
        fi
    done
}

canonical() {
    case "$1:$2" in
        "$VMS_DIR:nx" | "$VMS_DIR:nx_witness") echo "nxwitness" ;;
        "$APP_DIR:ld" | "$APP_DIR:loitering_detection") echo "object_detection" ;;
        "$APP_DIR:live_captioning") echo "lvc" ;;
        *) echo "$2" ;;
    esac
}

contains() {
    local needle="$1" item
    shift
    for item in "$@"; do
        if [[ "$item" == "$needle" ]]; then
            return 0
        fi
    done
    return 1
}

# Validate the comma-separated list $3 against shim directory $1 and append the
# canonical names, without duplicates, to the array named $4.
select_shims() {
    local dir="$1" label="$2" list="$3" item name
    local -n selected="$4"
    local -a items
    IFS=',' read -r -a items <<< "$list"
    for item in "${items[@]}"; do
        item="${item//[[:space:]]/}"
        if [[ -z "$item" ]]; then
            continue
        fi
        name="$(canonical "$dir" "${item,,}")"
        if [[ ! "$name" =~ ^[a-z0-9_]+$ || ! -f "$ROOT/$dir/$name/$FRAGMENT" ]]; then
            die "unknown $label '$item'. Available: $(available "$dir" | paste -sd, -)"
        fi
        if ! contains "$name" "${selected[@]}"; then
            selected+=("$name")
        fi
    done
    if [[ ${#selected[@]} -eq 0 ]]; then
        die "no $label selected"
    fi
}

strip_license() {
    sed -E '/^# (SPDX-|Copyright)/d' "$1"
}

# Fragments are top-level YAML lists; indent them under their parent key.
emit_fragment() {
    strip_license "$1" | sed -E 's/^(.+)$/  \1/'
}

generate() {
    local name
    cat <<EOF
# SPDX-FileCopyrightText: (C) $(date +%Y) Intel Corporation
# SPDX-License-Identifier: Apache-2.0
#
$MARKER --vms $(IFS=,; echo "${vms[*]}") --apps $(IFS=,; echo "${apps[*]}")
# Do not edit: change the $FRAGMENT fragments or config/base.yaml and re-run setup.sh.
# All \${ENV_VAR} references are resolved from environment variables at startup.

vms_instances:
EOF
    for name in "${vms[@]}"; do
        emit_fragment "$ROOT/$VMS_DIR/$name/$FRAGMENT"
    done
    printf '\nanalytics_apps:\n'
    for name in "${apps[@]}"; do
        emit_fragment "$ROOT/$APP_DIR/$name/$FRAGMENT"
    done
    printf '\n'
    strip_license "$BASE"
}

# Warn about ${VAR} placeholders without a default that are unset in .env.
# Only variable names are printed, never values.
check_env() {
    local env_file="$ROOT/.env" var value
    local -a missing=()
    if [[ ! -f "$env_file" ]]; then
        warn ".env not found: copy .env.example to .env and set the variables of the selected VMS and apps"
        return
    fi
    for var in $(grep -ohE '\$\{[A-Za-z_][A-Za-z0-9_]*\}' "$@" | tr -d '${}' | sort -u || true); do
        value="$(grep -E "^${var}=" "$env_file" | tail -n 1 | cut -d= -f2- || true)"
        value="${value%\"}"
        value="${value#\"}"
        if [[ -z "$value" || "$value" =~ ^\<.*\>$ ]]; then
            missing+=("$var")
        fi
    done
    if [[ ${#missing[@]} -gt 0 ]]; then
        warn "set these variables in .env before starting VAP: ${missing[*]}"
    fi
}

vms_arg=""
apps_arg=""
output="$ROOT/config/config.yaml"
force=false

while [[ $# -gt 0 ]]; do
    case "$1" in
        --vms | --apps | --output)
            if [[ $# -lt 2 || "$2" == --* ]]; then
                die "$1 needs a value"
            fi
            case "$1" in
                --vms) vms_arg="$2" ;;
                --apps) apps_arg="$2" ;;
                --output) output="$2" ;;
            esac
            shift 2
            ;;
        --vms=*) vms_arg="${1#*=}"; shift ;;
        --apps=*) apps_arg="${1#*=}"; shift ;;
        --output=*) output="${1#*=}"; shift ;;
        --force) force=true; shift ;;
        --list)
            echo "VMS:  $(available "$VMS_DIR" | paste -sd, -)"
            echo "Apps: $(available "$APP_DIR" | paste -sd, -)"
            exit 0
            ;;
        -h | --help) usage; exit 0 ;;
        *)
            usage >&2
            die "unknown argument '$1'"
            ;;
    esac
done

if [[ -z "$vms_arg" || -z "$apps_arg" ]]; then
    usage >&2
    die "both --vms and --apps are required"
fi

declare -a vms=() apps=()
select_shims "$VMS_DIR" "VMS" "$vms_arg" vms
select_shims "$APP_DIR" "app" "$apps_arg" apps

if [[ -f "$output" ]] && ! grep -qF "$MARKER" "$output"; then
    if [[ "$force" != true ]]; then
        die "$output was not generated by setup.sh; re-run with --force to replace it (it is kept as $output.bak)"
    fi
    cp -p "$output" "$output.bak"
    warn "previous $output saved as $output.bak"
fi

tmp="$(mktemp "$output.XXXXXX")"
trap 'rm -f "$tmp"' EXIT
generate > "$tmp"
# The backend container reads the file through a bind mount as a non-root user.
chmod 644 "$tmp"
mv "$tmp" "$output"
trap - EXIT

fragments=("$BASE")
for name in "${vms[@]}"; do fragments+=("$ROOT/$VMS_DIR/$name/$FRAGMENT"); done
for name in "${apps[@]}"; do fragments+=("$ROOT/$APP_DIR/$name/$FRAGMENT"); done
check_env "${fragments[@]}"

echo "Wrote $output (VMS: ${vms[*]}; apps: ${apps[*]})."
echo "Start VAP with 'docker compose up -d', or apply to a running VAP with 'docker compose restart backend'."
